/**
 * Grant deadlines as calendar dates in America/New_York, shared by the admin review queue and the
 * processing-queue email so both label a grant the same way.
 */

import { BatchGetItemCommand } from "@aws-sdk/client-dynamodb";
import { marshall, unmarshall } from "@aws-sdk/util-dynamodb";

/** Review statuses still waiting on an admin; reprocess and quarantine supersede the same set. */
export const OPEN_REVIEW_STATUSES = ["pending_review", "failed", "needs_reupload"];

export const DUE_SOON_DAYS = 7;
export const DUE_UPCOMING_DAYS = 30;

const DAY_MS = 86_400_000;
const easternDate = new Intl.DateTimeFormat("en-CA", {
  timeZone: "America/New_York",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
});

/** Today's date in Eastern time, YYYY-MM-DD. */
export function easternToday(now = new Date()) {
  return easternDate.format(now);
}

/** The leading YYYY-MM-DD of a stored deadline, or null. A time part is ignored on purpose. */
export function deadlineDateOf(value) {
  const match = typeof value === "string" ? value.match(/^(\d{4})-(\d{2})-(\d{2})/) : null;
  if (!match) return null;
  const [, y, m, d] = match.map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  return date.getUTCMonth() === m - 1 && date.getUTCDate() === d ? match[0] : null;
}

function isRolling(meta) {
  return meta?.is_rolling === true || meta?.is_rolling === "true";
}

/**
 * Deadline facts for one grant's metadata row (or undefined when the row is missing).
 * urgency: "expired" | "due_soon" (≤7 days) | "upcoming" (≤30) | "later" | null (no known deadline).
 * A rolling grant has no deadline, whatever expiration_date says.
 */
export function grantDeadline(meta, now = new Date()) {
  const deadline = isRolling(meta) ? null : deadlineDateOf(meta?.expiration_date);
  if (!deadline) return { deadline: null, daysLeft: null, urgency: null };
  const daysLeft = Math.round((Date.parse(deadline) - Date.parse(easternToday(now))) / DAY_MS);
  const urgency =
    daysLeft < 0 ? "expired"
    : daysLeft <= DUE_SOON_DAYS ? "due_soon"
    : daysLeft <= DUE_UPCOMING_DAYS ? "upcoming"
    : "later";
  return { deadline, daysLeft, urgency };
}

/** "Expired", "Due today", "Due in N days", or "" when no badge applies (unknown or >30 days). */
export function deadlineLabel({ daysLeft, urgency }) {
  if (urgency === "expired") return "Expired";
  if (urgency !== "due_soon" && urgency !== "upcoming") return "";
  if (daysLeft === 0) return "Due today";
  return `Due in ${daysLeft} day${daysLeft === 1 ? "" : "s"}`;
}

function rank(daysLeft) {
  if (daysLeft == null) return 1;
  return daysLeft < 0 ? 2 : 0;
}

/**
 * Soonest deadline first, then grants with no known deadline, then expired ones (most recently
 * expired first). Ties go to whichever has waited longest. Items carry daysLeft and created_at.
 */
export function compareByDeadline(a, b) {
  const ra = rank(a.daysLeft);
  const rb = rank(b.daysLeft);
  if (ra !== rb) return ra - rb;
  if (ra === 0 && a.daysLeft !== b.daysLeft) return a.daysLeft - b.daysLeft;
  if (ra === 2 && a.daysLeft !== b.daysLeft) return b.daysLeft - a.daysLeft;
  return String(a.created_at || "").localeCompare(String(b.created_at || ""));
}

/**
 * Metadata rows (deadline, grant status, scope) by NOFO name. A name with no row, or whose batch
 * could not be read, is simply absent, so callers must treat absence as "unknown".
 */
export async function readGrantMetadata(client, tableName, names) {
  const byName = new Map();
  const unique = [...new Set(names.filter(Boolean))];
  for (let i = 0; i < unique.length; i += 100) {
    let keys = unique.slice(i, i + 100).map((name) => marshall({ nofo_name: name }));
    try {
      for (let attempt = 0; keys.length > 0 && attempt < 4; attempt++) {
        const result = await client.send(
          new BatchGetItemCommand({
            RequestItems: {
              [tableName]: {
                Keys: keys,
                ProjectionExpression: "#n, #e, #s, #sc, #st, #r",
                ExpressionAttributeNames: {
                  "#n": "nofo_name",
                  "#e": "expiration_date",
                  "#s": "status",
                  "#sc": "scope",
                  "#st": "state",
                  "#r": "is_rolling",
                },
              },
            },
          })
        );
        for (const item of result.Responses?.[tableName] || []) {
          const row = unmarshall(item);
          byName.set(row.nofo_name, row);
        }
        keys = result.UnprocessedKeys?.[tableName]?.Keys || [];
        if (keys.length > 0) await new Promise((r) => setTimeout(r, 50 * 2 ** attempt));
      }
      if (keys.length > 0) console.warn(`Could not read metadata for ${keys.length} grant(s) after retries`);
    } catch (error) {
      console.warn("Could not read grant metadata:", error.message);
    }
  }
  return byName;
}
